<script module lang="ts">
/**
 * Wraps a control with its label, help text and error (`design/components/form-field.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/form-field.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, type Snippet } from 'svelte'

import {
  Icon,
  SlotOutlet,
  SlotScope,
  joinSlot,
  removeToast,
  toast,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/form-field.module.css'

export interface FormFieldControlProps {
  id?: string
  label?: string
  invalid?: boolean
  disabled?: boolean
  'aria-describedby'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
}

export interface FormFieldProps {
  /**
   * Exactly one governed control: Input, Select, Checkbox or Switch.
   */
  children: Snippet
  /**
   * Help text. Replaced by `error` when there is one, so they never show together.
   */
  description?: string
  /**
   * When non-empty, the field is invalid.
   */
  error?: string
  /**
   * Application errors show in toasts. The generic primitive keeps its explicit inline mode.
   */
  errorPresentation?: 'inline' | 'toast'
  /**
   * Base for the derived ids. Generated when omitted.
   */
  id?: string
  label: string
  /**
   * Content at the end of the label's row, as in the login block. By convention a Link, such as
   * "Forgot your password?" beside the Password label. It is a slot rather than a `link` prop,
   * because the field does not need to know what the content *is*. The field only defines that
   * the row has two ends and the label is at the start. A row-labelled control has no label row
   * of its own, so it ignores this prop.
   */
  labelEnd?: Snippet
  required?: boolean
}
</script>

<script lang="ts">
let {
  children,
  description,
  error,
  errorPresentation = 'inline',
  id: idOwn,
  label: labelOwn,
  labelEnd,
  required = false,
}: FormFieldProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const id = $derived(
  joined.passed['id'] === undefined ? idOwn : (joined.passed['id'] as typeof idOwn),
)
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const slots = {
  get default() {
    return children
  },
  get labelEnd() {
    return labelEnd
  },
}
const controlId = $derived(id ?? uid)
const descriptionId = $derived(`${controlId}-description`)
const errorId = $derived(`${controlId}-error`)
const labelId = $derived(`${controlId}-label`)
const invalid = $derived(error !== undefined && error !== '')
const inline = $derived(invalid && errorPresentation === 'inline')
const noticeId = $derived(`${controlId}-notice`)
const showDescription = $derived(description !== undefined && description !== '' && !invalid)
const describedBy = $derived(
  [inline ? errorId : undefined, showDescription ? descriptionId : undefined]
    .filter((value) => value !== undefined)
    .join(' ') || undefined,
)
const childrenScope: SlotScope = new SlotScope({
  pass: (): Record<string, unknown> => ({
    id: controlId,
    'aria-describedby': describedBy,
    'aria-required': required ? true : undefined,
    'aria-labelledby': (childrenScope.read().kind ?? 'field') === 'group' ? labelId : undefined,
    invalid: invalid ? true : undefined,
    label: (childrenScope.read().kind ?? 'field') === 'row-labelled' ? label : undefined,
  }),
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran =
    invalid && errorPresentation === 'toast'
      ? toast({
          id: noticeId,
          title: label,
          description: error,
          tone: 'danger',
          dismissible: true,
          retained: true,
          durationMs: Number.POSITIVE_INFINITY,
        })
      : ''
  release1 = () => {
    ran === '' || removeToast(ran)
  }
}
watchEffect(effect1, { watch: () => [invalid, errorPresentation, error, label] })
onDestroy(() => release1?.())
childrenScope.probe(() => children)
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    class={styles.field}
    data-kind={childrenScope.read().kind ?? 'field'}
    data-invalid={(invalid) ? '' : undefined}
    data-disabled={(childrenScope.read().props.disabled === true || childrenScope.read().props.disabled === '') ? '' : undefined}
    data-member="form-field"
    >{#if (childrenScope.read().kind ?? 'field') !== 'row-labelled'
      }<div class={styles.labelRow}
        ><label
          class={styles.label}
          id={((childrenScope.read().kind ?? 'field') === 'group') ? labelId : undefined}
          for={((childrenScope.read().kind ?? 'field') !== 'group') ? controlId : undefined}
          >{label
          }{#if required}<span class={styles.required} aria-hidden="true">{' *'}</span>{/if
        }</label
        >{#if slots.labelEnd}<span class={styles.labelEnd}>{@render labelEnd?.()}</span>{/if
      }</div
      >{#if showDescription}<p class={styles.description} id={descriptionId}>{description}</p>{/if
    }{/if
    }<SlotOutlet scope={childrenScope} snippet={children}
    />{#if (childrenScope.read().kind ?? 'field') === 'row-labelled'
      }{#if showDescription}<p class={styles.description} id={descriptionId}>{description}</p>{/if
    }{/if
    }{#if inline
      }<p class={styles.error} id={errorId}
        ><span class={styles.glyph}><Icon name="error" size="sm" /></span
        >{error
      }</p
    >{/if
  }</div
>{/if
}{@render joined.end?.()}
